// A source file may not pass LIMIT lines. Files already over it sit in
// scripts/file-size-allowlist.json with a cap (their line count when listed): a listed
// file may not grow past its cap. A listed file that shrank, or is gone, is only reported
// (the cleanup PR removes the entry), so parallel split PRs never conflict on the list.
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";

export const LIMIT = 1000;
const COUNTED = /\.(rs|ts|tsx|swift|css|mjs|js|sh|ps1)$/;
// Generated by tauri-specta from the Rust commands (AGENTS.md: never edit by hand).
const GENERATED = new Set(["src/bindings.ts"]);

export interface SizeReport {
  problems: string[];
  notes: string[];
}

export function sizeProblems(
  files: Map<string, number>,
  allowlist: Record<string, number>,
  limit = LIMIT,
): SizeReport {
  const problems: string[] = [];
  const notes: string[] = [];
  for (const [file, lines] of files) {
    const cap = allowlist[file];
    if (cap === undefined) {
      if (lines > limit) {
        problems.push(
          `${file}: ${lines} lines, limit ${limit}. Split it (AGENTS.md, "Code Style").`,
        );
      }
    } else if (lines > cap) {
      problems.push(
        `${file}: grew to ${lines} lines, its cap is ${cap}. Move code out, do not add.`,
      );
    } else if (lines <= limit) {
      notes.push(`${file}: ${lines} lines, remove it from the allowlist`);
    } else if (lines < cap) {
      notes.push(`${file}: ${lines} lines, lower its cap from ${cap}`);
    }
  }
  for (const file of Object.keys(allowlist)) {
    if (!files.has(file))
      notes.push(`${file}: gone, remove it from the allowlist`);
  }
  return { problems, notes };
}

function countLines(file: string): number {
  return readFileSync(file, "utf8").split("\n").length - 1;
}

function main(): void {
  const root = execFileSync("git", ["rev-parse", "--show-toplevel"], {
    encoding: "utf8",
  }).trim();
  process.chdir(root);
  const tracked = execFileSync("git", ["ls-files", "-z"], {
    encoding: "utf8",
    maxBuffer: 1 << 26,
  })
    .split("\0")
    .filter((f) => f && COUNTED.test(f) && !GENERATED.has(f) && existsSync(f));
  const files = new Map(tracked.map((f) => [f, countLines(f)]));
  const allowlist = JSON.parse(
    readFileSync("scripts/file-size-allowlist.json", "utf8"),
  ) as Record<string, number>;
  const { problems, notes } = sizeProblems(files, allowlist);
  for (const note of notes) console.warn(`note: ${note}`);
  if (problems.length > 0) {
    console.error(problems.join("\n"));
    process.exit(1);
  }
  console.log(
    `${files.size} source files, none over ${LIMIT} lines beyond the allowlist (${Object.keys(allowlist).length} listed)`,
  );
}

if (import.meta.main) main();
